import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.util.Arrays;
import java.security.Signature;
import java.security.MessageDigest;

public class KeyPairTest {

    @Test
    public void canSign_ReturnsFalse_WhenKeyIsInvalid() {
        // Arrange and Act
        boolean result = new KeyPair(new EdDSAPublicKey()).canSign();

        // Assert
        assertFalse(result);
    }

    @Test
    public void fromSecretSeed_WithByteArraySeed_ReturnsValidKeyPair() throws Exception {
        // Arrange
        byte[] seed = "secretpassword".getBytes();
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        XdrDataOutputStream writer = new XdrDataOutputStream(outputStream);

        // Act
        KeyPair keyPair = KeyPair.fromSecretSeed(seed);

        // Assert
        assertNotNull(keyPair);
        assertEquals(16, keyPair.getPublicKey().length);
    }

    @Test
    public void fromPublicXdrKey_WithByteArrayKey_ReturnsValidKeyPair() {
        // Arrange
        byte[] publicKey = "publickey".getBytes();
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        XdrDataOutputStream writer = new XdrDataOutputStream(outputStream);

        // Act
        KeyPair keyPair = KeyPair.fromXdrPublicKey(PublicKey.of(publicKey));

        // Assert
        assertNotNull(keyPair);
    }

    @Test
    public void random_ReturnsValidKeyPair() throws Exception {
        // Arrange and Act
        KeyPair keyPair = KeyPair.random();

        // Assert
        assertNotNull(keyPair);
        assertNotNull(keyPair.getPublicKey());
    }
}
